'use strict';
async function taskControls(card,t,refresh){const b=el('button','Workflow controls / evidence'),panel=el('div');card.append(b,panel);b.onclick=async()=>{try{const j=await api('main/controls/task?id='+encodeURIComponent(t.id)),p=j.control||{};panel.replaceChildren(el('p',`Prerequisite: ${p.predecessor_id||'None'} · Reviewer: ${p.reviewer_id||'None'} · Review: ${p.reviewed_at||'Not approved'} · Evidence: ${p.evidence_required?'Required':'Optional'} (${p.evidence_id||'Not linked'})`));if(admin()&&t.current_status==='ASSIGNED'){const f=el('form',undefined,'gridform');const pred=wfField(f,'Prerequisite task','predecessor_id',[['','None'],...j.tasks.map(x=>[x.id,x.task_text])], 'text',false);pred.value=p.predecessor_id||'';const rev=wfField(f,'Independent reviewer','reviewer_id',[['','None'],...j.staff.map(x=>[x.id,x.display_name])],'text',false);rev.value=p.reviewer_id||'';const req=wfField(f,'Verified evidence required','evidence_required',[['0','No'],['1','Yes']]);req.value=p.evidence_required?'1':'0';const due=wfField(f,'Stage deadline','due_date',null,'date',false);due.value=String(t.due_date||'').slice(0,10);wfSubmit(f,'Save controls',async data=>{await api('main/controls/configure',{...data,task_id:t.id});await refresh();});panel.append(f);}if(admin()&&j.control&&j.files.length&&!['COMPLETED','CANCELLED'].includes(t.current_status)){const f=el('form',undefined,'gridform');wfField(f,'Verified job document','file_id',j.files.map(x=>[x.id,x.filename]));wfSubmit(f,'Link evidence',async data=>{await api('main/controls/evidence',{...data,task_id:t.id});await refresh();});panel.append(f);}if(admin()&&j.history.length)panel.append(table(j.history,[['Action','action'],['Actor','actor'],['Date','created_at']]));}catch(e){notice(e.message);}};}
async function designatedReviews(c,run){const j=await api('main/controls/reviews');if(run!==generation)return;const v=document.createDocumentFragment();v.append(el('p','Your designated review assignments. Administrator final approval is separate.'));for(const t of j.rows){const card=el('section',undefined,'card');card.append(el('h3',t.task_text),el('p',t.reviewed_at?'Reviewed: '+t.reviewed_at:'Awaiting your review'));if(!t.reviewed_at){const f=el('form',undefined,'gridform');wfField(f,'Review findings','note',null,'textarea');wfSubmit(f,'Approve review',async data=>{await api('main/controls/review',{...data,task_id:t.task_id});await load();});card.append(f);}v.append(card);}if(!j.rows.length)v.append(el('p','No assigned reviews.'));c.replaceChildren(v);}
